package com.mcblause;
import org.bukkit.*;import org.bukkit.attribute.Attribute;import org.bukkit.command.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.EntityDamageByEntityEvent;import org.bukkit.event.entity.EntityDeathEvent;import org.bukkit.event.player.PlayerJoinEvent;import org.bukkit.event.player.PlayerQuitEvent;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.potion.*;import java.io.File;import java.util.*;
public final class McBlause extends JavaPlugin implements Listener,CommandExecutor,TabCompleter{
 private NamespacedKey key;private UUID bossId;private LivingEntity boss;private BossBar bar;private int timer=3600;private long slamTime,waveTime;private final Map<UUID,Double> damage=new HashMap<>();private final Map<UUID,String> names=new HashMap<>();private File bossFile,damageFile,arenaFile;private YamlConfiguration bd,dd,ad;private final Random rng=new Random();
 public void onEnable(){saveDefaultConfig();for(String f:new String[]{"boss.yml","rewards.yml","messages.yml","arena.yml","damage.yml"})if(!new File(getDataFolder(),f).exists())saveResource(f,false);key=new NamespacedKey(this,"boss_marker");bossFile=new File(getDataFolder(),"boss.yml");damageFile=new File(getDataFolder(),"damage.yml");arenaFile=new File(getDataFolder(),"arena.yml");loadFiles();loadDamage();getServer().getPluginManager().registerEvents(this,this);getCommand("boss").setExecutor(this);getCommand("boss").setTabCompleter(this);restoreBoss();if(boss!=null)makeBar();timer=Math.max(0,bd.getInt("timer-remaining",getConfig().getInt("respawn-seconds",3600)));getServer().getScheduler().runTaskTimer(this,()->{if(boss!=null&&boss.isValid())return;if(!getConfig().getBoolean("enabled",true))return;if(timer>0)timer--;if(timer<=0)spawn(false);saveBoss();},20,20);getServer().getScheduler().runTaskTimer(this,this::abilities,20,20);}
 public void onDisable(){saveBoss();saveDamage();if(bar!=null)bar.removeAll();}
 private void loadFiles(){bd=YamlConfiguration.loadConfiguration(bossFile);ad=YamlConfiguration.loadConfiguration(arenaFile);}private void saveBoss(){bd.set("uuid",bossId==null?"":bossId.toString());bd.set("timer-remaining",timer);try{bd.save(bossFile);}catch(Exception e){getLogger().warning(e.getMessage());}}
 private void loadDamage(){dd=YamlConfiguration.loadConfiguration(damageFile);damage.clear();names.clear();var section=dd.getConfigurationSection("players");if(section!=null)for(String id:section.getKeys(false))try{UUID u=UUID.fromString(id);damage.put(u,dd.getDouble("players."+id+".damage"));names.put(u,dd.getString("players."+id+".name",id));}catch(Exception ignored){}}
 private void saveDamage(){dd.set("players",null);for(UUID u:damage.keySet()){dd.set("players."+u+".damage",damage.get(u));dd.set("players."+u+".name",names.getOrDefault(u,u.toString()));}try{dd.save(damageFile);}catch(Exception e){getLogger().warning(e.getMessage());}}
 private void restoreBoss(){try{Entity e=Bukkit.getEntity(UUID.fromString(bd.getString("uuid","")));if(e instanceof LivingEntity l&&l.getPersistentDataContainer().has(key,PersistentDataType.BYTE)){boss=l;bossId=l.getUniqueId();}}catch(Exception ignored){}}
 private Location bossLoc(){World w=Bukkit.getWorld(bd.getString("spawn.world",getConfig().getString("arena.spawn.world","world")));if(w==null)w=Bukkit.getWorlds().get(0);return new Location(w,bd.getDouble("spawn.x",.5),bd.getDouble("spawn.y",80),bd.getDouble("spawn.z",.5),(float)bd.getDouble("spawn.yaw",0),(float)bd.getDouble("spawn.pitch",0));}
 private void spawn(boolean announce){if(!getConfig().getBoolean("enabled",true)){if(announce)broadcast(message("boss-disabled"));return;}if(boss!=null&&boss.isValid()){if(announce)broadcast("&cBoss is already alive.");return;}EntityType type;try{type=EntityType.valueOf(getConfig().getString("boss.entity","ZOMBIE").toUpperCase(Locale.ROOT));}catch(Exception e){type=EntityType.ZOMBIE;}Entity entity=bossLoc().getWorld().spawnEntity(bossLoc(),type);Mob mob;if(entity instanceof Mob)mob=(Mob)entity;else{entity.remove();mob=(Mob)bossLoc().getWorld().spawnEntity(bossLoc(),EntityType.ZOMBIE);}boss=mob;bossId=mob.getUniqueId();mob.getPersistentDataContainer().set(key,PersistentDataType.BYTE,(byte)1);mob.setPersistent(true);mob.setRemoveWhenFarAway(false);mob.setCustomName(ChatColor.translateAlternateColorCodes('&',getConfig().getString("boss.display-name","&c&lTHE BLAUSE")));mob.setCustomNameVisible(true);mob.setGlowing(getConfig().getBoolean("boss.glowing",true));mob.setFireTicks(getConfig().getBoolean("boss.fire",false)?Integer.MAX_VALUE:0);double hp=Math.max(1,getConfig().getDouble("boss.max-health",100));if(mob.getAttribute(Attribute.MAX_HEALTH)!=null){mob.getAttribute(Attribute.MAX_HEALTH).setBaseValue(hp);mob.setHealth(hp);}if(mob.getAttribute(Attribute.SCALE)!=null)mob.getAttribute(Attribute.SCALE).setBaseValue(getConfig().getDouble("boss.scale",1.35));if(mob instanceof Zombie z)z.setAdult();equip(mob);effects(mob);damage.clear();names.clear();saveDamage();timer=getConfig().getInt("respawn-seconds",3600);makeBar();if(announce)broadcast(message("boss-spawned"));saveBoss();}
 private void equip(Mob m){if(!(m instanceof Zombie z))return;var c=getConfig().getConfigurationSection("boss.equipment");if(c==null)return;var e=z.getEquipment();e.setHelmet(item(c.getString("helmet")));e.setChestplate(item(c.getString("chestplate")));e.setLeggings(item(c.getString("leggings")));e.setBoots(item(c.getString("boots")));e.setItemInMainHand(item(c.getString("weapon")));e.setHelmetDropChance(0);e.setChestplateDropChance(0);e.setLeggingsDropChance(0);e.setBootsDropChance(0);e.setItemInMainHandDropChance(0);}
 private org.bukkit.inventory.ItemStack item(String s){try{return s==null?null:new org.bukkit.inventory.ItemStack(Material.valueOf(s.toUpperCase(Locale.ROOT)));}catch(Exception e){return null;}}
 private void effects(LivingEntity l){for(String s:getConfig().getStringList("boss.effects"))try{String[] p=s.split(":");PotionEffectType t=PotionEffectType.getByName(p[0].toUpperCase(Locale.ROOT));if(t!=null)l.addPotionEffect(new PotionEffect(t,Integer.MAX_VALUE,Integer.parseInt(p.length>1?p[1]:"0")),true);}catch(Exception ignored){}}
 private void makeBar(){if(bar!=null)bar.removeAll();BarColor c;BarStyle st;try{c=BarColor.valueOf(getConfig().getString("bar.color","RED"));}catch(Exception e){c=BarColor.RED;}try{st=BarStyle.valueOf(getConfig().getString("bar.style","SEGMENTED_10"));}catch(Exception e){st=BarStyle.SEGMENTED_10;}bar=Bukkit.createBossBar(ChatColor.translateAlternateColorCodes('&',getConfig().getString("boss.display-name","&c&lTHE BLAUSE")),c,st);bar.setProgress(1);for(Player p:Bukkit.getOnlinePlayers())bar.addPlayer(p);}
 @EventHandler public void onJoin(PlayerJoinEvent e){if(bar!=null)bar.addPlayer(e.getPlayer());}@EventHandler public void onQuit(PlayerQuitEvent e){if(bar!=null)bar.removePlayer(e.getPlayer());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void hit(EntityDamageByEntityEvent e){if(boss==null||!e.getEntity().getUniqueId().equals(bossId))return;Player p=null;Entity d=e.getDamager();if(d instanceof Player)p=(Player)d;else if(d instanceof Projectile pr&&pr.getShooter() instanceof Player)p=(Player)pr.getShooter();else if(d instanceof Tameable t&&t.getOwner() instanceof Player)p=(Player)t.getOwner();if(p!=null&&e.getFinalDamage()>0){damage.merge(p.getUniqueId(),e.getFinalDamage(),Double::sum);names.put(p.getUniqueId(),p.getName());saveDamage();if(bar!=null&&boss.getAttribute(Attribute.MAX_HEALTH)!=null)bar.setProgress(Math.max(0,Math.min(1,boss.getHealth()/boss.getAttribute(Attribute.MAX_HEALTH).getBaseValue())));}}
 @EventHandler public void onDeath(EntityDeathEvent e){if(boss==null||!e.getEntity().getUniqueId().equals(bossId))return;rewards(e.getEntity().getKiller());broadcast(message("boss-dead"));if(bar!=null)bar.removeAll();boss=null;bossId=null;timer=getConfig().getInt("respawn-seconds",3600);bd.set("uuid","");saveBoss();}
 private void rewards(Player killer){if(!getConfig().getBoolean("rewards.enabled",true))return;YamlConfiguration r=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"rewards.yml"));if(!r.getBoolean("enabled",true))return;if(killer!=null)runCmd(r.getString("killer-command","eco give %player% 100m"),killer.getName(),null);String mode=r.getString("participant.mode","RANDOM");for(UUID u:damage.keySet()){if(killer!=null&&u.equals(killer.getUniqueId()))continue;Player p=Bukkit.getPlayer(u);if(p==null)continue;double amount;if(mode.equalsIgnoreCase("DAMAGE"))amount=damage.get(u)*r.getDouble("participant.damage-percent",.35);else{int min=r.getInt("participant.min",1000000),max=r.getInt("participant.max",20000000);amount=min+rng.nextDouble(Math.max(1,max-min+1));}runCmd(r.getString("command-format","eco give %player% %amount%"),p.getName(),String.format(Locale.US,"%.0f",amount));}}
 private void runCmd(String cmd,String player,String amount){if(cmd!=null&&!cmd.isBlank())Bukkit.dispatchCommand(Bukkit.getConsoleSender(),cmd.replace("%player%",player).replace("%amount%",amount==null?"":amount));}
 private List<Player> nearby(Location l,double rad){return l.getWorld().getPlayers().stream().filter(p->p.getLocation().distanceSquared(l)<=rad*rad).toList();}
 private void abilities(){if(!(boss instanceof Mob mob)||!boss.isValid()||!getConfig().getBoolean("abilities.enabled",true))return;Player t=mob.getTarget();if(t==null)t=Bukkit.getOnlinePlayers().stream().filter(p->p.getWorld().equals(boss.getWorld())).min(Comparator.comparingDouble(p->p.getLocation().distanceSquared(boss.getLocation()))).orElse(null);if(t==null)return;mob.setTarget(t);long now=System.currentTimeMillis();double sr=getConfig().getDouble("abilities.slam.radius",5);if(now-slamTime>getConfig().getLong("abilities.slam.cooldown-seconds",12)*1000L&&t.getLocation().distance(boss.getLocation())<=sr){slamTime=now;for(Player p:nearby(boss.getLocation(),sr)){p.damage(getConfig().getDouble("abilities.slam.damage",8),boss);p.setVelocity(p.getLocation().toVector().subtract(boss.getLocation().toVector()).normalize().multiply(getConfig().getDouble("abilities.slam.knockback",1.25)).setY(.6));}boss.getWorld().spawnParticle(Particle.EXPLOSION,boss.getLocation(),1);boss.getWorld().playSound(boss.getLocation(),Sound.ENTITY_GENERIC_EXPLODE,1.3f,.8f);}if(now-waveTime>getConfig().getLong("abilities.shockwave.cooldown-seconds",20)*1000L){waveTime=now;boss.getWorld().spawnParticle(Particle.SONIC_BOOM,boss.getLocation(),1);for(Player p:nearby(boss.getLocation(),getConfig().getDouble("abilities.shockwave.radius",8)))p.damage(getConfig().getDouble("abilities.shockwave.damage",5),boss);}}
 private String message(String k){YamlConfiguration m=YamlConfiguration.loadConfiguration(new File(getDataFolder(),"messages.yml"));return ChatColor.translateAlternateColorCodes('&',m.getString("prefix","")+m.getString(k,""));}
 private void broadcast(String s){Bukkit.broadcastMessage(ChatColor.translateAlternateColorCodes('&',s));}
 private void status(CommandSender s){if(boss!=null&&boss.isValid())s.sendMessage(message("boss-alive")+ChatColor.GRAY+" HP: "+String.format(Locale.US,"%.1f",boss.getHealth())+"/"+getConfig().getDouble("boss.max-health",100));else s.sendMessage(ChatColor.YELLOW+"Respawn in "+timer+"s");s.sendMessage(message("leaderboard-title"));List<Map.Entry<UUID,Double>> top=damage.entrySet().stream().sorted(Map.Entry.<UUID,Double>comparingByValue().reversed()).limit(getConfig().getInt("leaderboard.show-top",10)).toList();int n=1;for(var entry:top)s.sendMessage(ChatColor.GRAY+"#"+(n++)+" "+names.getOrDefault(entry.getKey(),"Unknown")+ChatColor.WHITE+" : "+String.format(Locale.US,"%.1f",entry.getValue()));}
 private void arenaTp(Player p){YamlConfiguration a=YamlConfiguration.loadConfiguration(arenaFile);World w=Bukkit.getWorld(a.getString("world","world"));if(w==null){p.sendMessage(ChatColor.RED+"Arena world unavailable.");return;}p.teleport(new Location(w,a.getDouble("x"),a.getDouble("y"),a.getDouble("z"),(float)a.getDouble("yaw"),(float)a.getDouble("pitch")));p.sendMessage(message("teleported"));}
 public boolean onCommand(CommandSender s,Command c,String label,String[] a){if(a.length==0||a[0].equalsIgnoreCase("info")){status(s);return true;}if(a[0].equalsIgnoreCase("arena")){if(!(s instanceof Player)){s.sendMessage("Players only.");return true;}if(!s.hasPermission("boss.use")){s.sendMessage(message("no-permission"));return true;}arenaTp((Player)s);return true;}if(!s.hasPermission("boss.admin")){s.sendMessage(message("no-permission"));return true;}switch(a[0].toLowerCase(Locale.ROOT)){case "spawn":spawn(true);s.sendMessage(message("spawned"));break;case "kill":if(boss!=null&&boss.isValid()){boss.remove();boss=null;bossId=null;if(bar!=null)bar.removeAll();timer=getConfig().getInt("respawn-seconds",3600);saveBoss();s.sendMessage(message("killed"));}else s.sendMessage(message("boss-not-active"));break;case "setarena":if(!(s instanceof Player)){s.sendMessage("Players only.");break;}Location l=((Player)s).getLocation();ad.set("world",l.getWorld().getName());ad.set("x",l.getX());ad.set("y",l.getY());ad.set("z",l.getZ());ad.set("yaw",l.getYaw());ad.set("pitch",l.getPitch());try{ad.save(arenaFile);s.sendMessage(message("arena-set"));}catch(Exception ex){s.sendMessage(ChatColor.RED+"Save failed.");}break;case "reload":reloadConfig();loadFiles();loadDamage();s.sendMessage(message("reloaded"));break;default:s.sendMessage(ChatColor.YELLOW+"/boss [info|arena|spawn|kill|setarena|reload]");}return true;}
 public List<String> onTabComplete(CommandSender s,Command c,String a,String[] args){if(args.length==1&&s.hasPermission("boss.admin"))return Arrays.asList("info","arena","spawn","kill","setarena","reload").stream().filter(v->v.startsWith(args[0].toLowerCase(Locale.ROOT))).toList();return Collections.emptyList();}
}
